  z''= zeros(b₂, t_n, t_r)
  for b_1 in range(0, b₁):               // 循环b₁维度 (非并行)
    s = S[b_1, :, r_start:r_end].view(b₂, 1, t_r)  // load S tile
    z' = zeros(t_n, t_r)
    for p_tile:                           // 第一个bmm (tensor core)
