  z''= zeros(b₂, t_n, t_r)
  for b_1 in 0..b₁-1:                     // 循环而非并行b₁维度
    s = S[b_1, :, r_s:r_e].view(b₂, 1, t_r)
    z' = zeros(t_n, t_r)
    for p_tile:                            // 第一个bmm (tensor core)
      x = X[b_1, n_s:n_e, p_s:p_e]; v = V[b_1, p_s:p_e, r_s:r_e]
      z' += dot(x, v)
    z'' += s * z'                          // S-weighted累加 (CUDA core)
